def edit(p, pairs):
    s=open(p).read()
    for a,b in pairs:
        assert s.count(a)==1, (p,a[:70])
        s=s.replace(a,b)
    open(p,'w').write(s)
edit('item_reexports.av',[("""/// Every `export use` line the written item `at` of `file` writes: none read back where the item's
/// own facts (its `about`, kept beside its tape) hold no `export use` at all.
fn reexports_in(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Reexport> {
    if !item_reexports(engine, file, at) { return [] }
    uses_in(engine, file, at).filter(it.line.exported)
}

/// Whether the written item `at` of `file` writes an `export use`, as its `about` keeps its `use` lines.
fn item_reexports(engine: QueryEngine, file: SourceFileAddress, at: int) -> bool { about_of(item_parts_part(engine, file, about_part(at))).uses.any(it.exported) }""","""/// Every `export use` line the written item `at` of `file` writes: no item read back where its file's
/// words (`file_words`, read once a file) hold no `export use` at all.
fn reexports_in(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Reexport> {
    if !file_words(engine, file).uses.any(it.exported) { return [] }
    uses_in(engine, file, at).filter(it.line.exported)
}""")])
s=open('item_refused.av').read()
i=s.index("/// The `within` at `at` refused: its block answering nothing")
j=s.index("fn within_words(")
s=s[:i]+"""/// A `within` refused: its block answering nothing, or a program loading no `@std/time` for it —
/// nothing built for an item whose typing refused nothing, as most items' does.
fn withins_refused(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Found> {
    let rows = refused_in(engine, file, at)
    if rows.is_empty() { return [] }
    flatten(
        [match r.seat { .Within(untimed) -> found_saying(r, [if untimed { "untimed" } else { "" }]), _ -> [] } for r in rows],
    )
}

/// a `within` answers its block or the deadline it ran past
export law within_answers {
    kind: "type.within"
    reads: withins_refused
    voice: within_words
    witness: "use @std.time.{ms}\\nlet r = within ms(100) {\\n    let a = 1\\n}\\n0\\n"
}

"""+s[j:]
s=s.replace("    Annotation,\n    At,\n    NodeKind,\n","    Annotation,\n",1)
open('item_refused.av','w').write(s)
EOF
cd /work/avra-dev && . /etc/profile.d/avra.sh && build/avra-try fmt --write $(git diff --name-only | grep '\.av$') | tail -1; AVRA_PROGRAM_NET=0 timeout 1500 make try 2>&1 | grep -E "^error|^ *╭|^[0-9]+ │|try:" | head; timeout 1500 sh tools/witness_program_refusal.sh build/avra-try within_answers_nothing 2>&1 | tail -1; cd /tmp/claude-0/-home-user/538a4aee-c2f6-55cb-b37f-192e296f9c1f/scratchpad/gaps/probe && rm -rf .avra-cache && KINDS=type.within,resolve.reexport_cycle AVRA_PROGRAM=0 timeout 1200 /work/avra-dev/build/avra-try run . 2>/dev/null | grep -E "^===|^error"

