cat /tmp/claude-0/-home-user/538a4aee-c2f6-55cb-b37f-192e296f9c1f/tasks/bgdxhkvpt.output; cd /work && python3 - <<'EOF'
import re,collections
def rows(p):
    d={}
    for l in open(p):
        m=re.match(r"cost: (\S+) (\S+)(?: fell)?: (\d+) -> (\d+)",l)
        if m: d[(m.group(1),m.group(2))]=int(m.group(4))
    return d
h=rows('avra-dev/build/gate/cost/cost.log'); b=rows('avra-base/build/gate/cost/cost.log')
print(len(h),len(b))
over=[(k,b[k],h[k],(h[k]-b[k])/b[k]*100) for k in sorted(set(h)&set(b)) if b[k] and (h[k]-b[k])/b[k]*100>0.05]
for o in over: print("OVER", o[0], o[1], "->", o[2], f"{o[3]:+.3f}%")
print("over count", len(over))
def load(p):
    d=collections.Counter()
    for l in open(p):
        parts=l.split()
        if len(parts)>=4 and parts[1]=='site':
            try: d[parts[2]]+=int(parts[3])
            except: pass
    return d
dec=lambda s: re.sub(r'\$([0-9A-F]{2})', lambda m: chr(int(m.group(1),16)), s)
H=load('avra-dev/build/cost/check-cli.sites'); B=load('avra-base/build/cost/check-cli.sites')
diff=sorted(((H[k]-B.get(k,0)),k) for k in set(H)|set(B))
print("sites total", sum(H.values())-sum(B.values()))
for d,k in diff[-10:][::-1]: print(f"{d:+10d}  {dec(k)[3:]}")
EOF

