# collect enum gate
edit('item_decl_shapes.av',[("""fn enum_traits_untraited(view: ItemView) -> List<Found> {
    let item = view.item""","""fn enum_traits_untraited(view: ItemView) -> List<Found> {
    // the item's summary says what it declares, by kind: one declaring no `collect enum` is read no further
    if !item_declares(view.engine, view.file, view.at).any(ITEM_KINDS[it.kind] == ItemKind.CollectEnum) { return [] }
    let item = view.item""")])
# within: an `on:` law
