a=s[s.index("/// A `within` refused: its block answering nothing"):s.index("fn within_words(")]
b="""/// The `within` at `at` refused: its block answering nothing, or a program loading no `@std/time`
/// for it — read only where the item holds a `within`, the nodes a law walks handed it by kind.
fn within_refused_at(view: ItemView, at: At) -> List<Found> {
    let e? = match at { .Expr(x) -> x, rest -> null } else { return [] }
    let body? = match view.item.store.expr(e) { .Within(_, b) -> b, rest -> null } else { return [] }
    let store = view.item.store
    let mine = [store.expr_span(e), store.expr_span(body)]
    flatten(
        [match r.seat { .Within(untimed) -> found_saying(r, [if untimed { "untimed" } else { "" }]), _ -> [] } for r in refused_in(view.engine, view.file, view.at) if mine.any((sp) -> spanned(sp, r.at))],
    )
}

/// Whether the kept place `at` is the span `sp`.
fn spanned(sp: Span?, at: FindingAt?) -> bool {
    let s? = sp else { return false }
    let a? = at else { return false }
    s.lo == a.lo && s.hi == a.hi
}

/// a `within` answers its block or the deadline it ran past
export law within_answers {
    kind: "type.within"
    on: [NodeKind.ExprWithin]
    judge: within_refused_at
    quotes: false
    voice: within_words
    witness: "use @std.time.{ms}\\nlet r = within ms(100) {\\n    let a = 1\\n}\\n0\\n"
}

"""
s=s.replace(a,b); open('item_refused.av','w').write(s)
EOF
