/// no impl of a trait the enum is written over, where that trait derives none for it: at the
/// declaration, its voice handed the enum, the trait and the member.
fn members_unimplemented(view: ItemView) -> List<Found> {
    let owed? = package_owed_impls(view.engine, view.file.package_name)
