    let own = [d for d in file_declares_at(view.engine, view.file, view.at).names if d.item == view.at]
    if own.is_empty() { return [] }
    let package = view.file.package_name
    let enums = [d for p in package_sources(view.engine, package, "src") for d in file_declares(view.engine, SourceFileAddress { package_name: package, path_in_package: p })
        .names if d.kind == ItemKind.CollectEnum]
    [Found { at: declared_span(view, m.name), args: [e.name, t.name, m.name] } for e in enums for t in gathered_traits(view.engine, e.file, e.name, true) if !derives(view.engine, t) for members in some_list(members_of(view.engine, e.file, e.name, false, "")) for m in members if own.any(it.is(m)) && !written_traits(view.engine, m.file, m.name).contains(t.name)]
}

