    /// Why the LOADED `@std/meta` is not the one this compiler was
    /// built against — the first shape that moved, or null when every
    /// row agrees. A package the program does not load crosses
    /// nothing, and is no disagreement.
    fn meta_disagreement() -> string? {
        let moved: string? = flatten(
            [some_list(self.record_disagreement(row)) for row in meta_records()],
        )
            .first()
        moved ?? self.node_disagreement()
    }

    /// A record's fields, in order, against the row.
    fn record_disagreement(row: MetaShape) -> string? {
        let d? = self.package_decl(row.pkg, row.name) else { return null }
        let slots? = self.slot_names(d) else { return null }
        first_difference(row.name, slots, owed(row, slots.length))
    }
""","""/// A variant of the LOADED `@std/meta`'s `Node`: its name and how many payloads it carries.
export type NodeVariant = { name: string, arity: int }

/// THE ONE DOOR'S QUESTION, asked by either path of what it loaded: where a crossed record's slots
/// part from the row the crossing reads (`slots` answers a record's, by its package and name; absent
/// where the program loads none), else where `node`, the loaded `Node`'s variants, parts from the
/// readers; null where the loaded package is the one this compiler was built against.
export fn meta_moved_from(slots: fn(string, string) -> List<string>?, node: List<NodeVariant>?) -> string? {
    let moved: string? = flatten([some_list(record_moved(row, slots(row.pkg, row.name))) for row in meta_records()])
        .first()
    if moved != null { return moved }
    let loaded? = node else { return null }
    let rows = node_readers()
    let named: string? = first_difference("Node", [v.name for v in loaded], [r.name for r in rows])
    named ?? first_arity_moved(loaded, rows)
}

/// A record's loaded slots, in order, against its row.
fn record_moved(row: MetaShape, loaded: List<string>?) -> string? {
    let slots? = loaded else { return null }
    first_difference(row.name, slots, owed(row, slots.length))
}

/// The first variant of the loaded `Node` carrying FEWER payloads than the crossing reads — asked
/// only once the names agree, so the two runs are the same length. A variant that GREW one the
/// reader ignores is growth, and growth is not a moved shape.
fn first_arity_moved(loaded: List<NodeVariant>, rows: List<NodeReader>) -> string? {
    let at? = [j for j, r in rows if loaded[j].arity < r.arity].first() else { return null }
    "`Node.${rows[at].name}` carries ${loaded[at].arity} payloads where the crossing reads ${rows[at].arity}"
}

impl Decls {
