        let decls = self
        meta_moved_from(
            (pkg: string, name: string) -> {
                let d? = decls.package_decl(pkg, name) else { return null }
                decls.slot_names(d)
            },
            self.node_variants(),
        )
    }
"""),
("""    /// `Node`'s variants, in order and by payload count.
