        named ?? first_arity_difference(sig.payloads, rows)
    }""","""    /// The loaded `Node`'s variants, in order, each by its payload count; absent where none is loaded.
    fn node_variants() -> List<NodeVariant>? {
        let d? = self.package_decl("@std.meta", "Node") else { return null }
        let sig? = self.variants_of_type(self.self_type_of(d)) else { return null }
        [NodeVariant { name: n, arity: sig.payloads[j].length } for j, n in sig.names]
