fn no_task(mut cx: TypeCx, e: ExprId) -> TypeId {
    cx.spoken(said_as("flow.produce", cx.loc_of(e), taskless("produce", "Source")))
}

fn no_task_chan(mut cx: TypeCx, e: ExprId) -> TypeId {
    cx.spoken(said_as("flow.channel", cx.loc_of(e), taskless("channel", "Channel")))
}

/// The form `form`, which answers `@std/task`'s `answer`, in a program that loads no `@std/task`.
export fn taskless(form: string, answer: string) -> Voice {
    Voice {
        message: "`${form}` answers `@std.task.${answer}`, and this program loads no `@std/task`",
        label: "no `@std/task` here",
        help: "add `use @std.task`",
    }
}

fn answers_nothing(mut cx: TypeCx, body: ExprId) -> TypeId {
    cx
        .spoken(
            refusal(
                "type.within",
                cx.loc_of(body),
                "a `within` answers what its block did or the deadline it ran past, and this block answers nothing",
                "answers nothing",
                "answer what the block did — end it on a value",
            ),
        )
}

/// The limit is no span: `within` arms through `@std/time`'s own
/// `Duration`, so that is what its seat takes.
fn limit_unfit(mut cx: TypeCx, limit: ExprId, span: TypeId) -> TypeId {
    let shown = cx.view.types.name_of(span)
    cx
        .spoken(
            cx
                .seat_mismatch(
                    "type.mismatch",
                    cx.loc_of(limit),
                    limit,
                    "a `within`'s limit is a span of time — `${shown}`",
                    span,
                ),
        )
}

fn no_time(mut cx: TypeCx, e: ExprId) -> TypeId {
    cx
        .spoken(
            refusal(
                "type.within",
                cx.loc_of(e),
                "a `within` answers `Result<T, TimedOut>`, and `TimedOut` is `@std/time`'s",
                "no `@std/time` here",
                "give the limit as `@std/time`'s span — `use @std.time.{ms}`",
            ),
        )
}

fn cancelled_unloaded() -> Refusal {
    let said = catch_fault(CatchFault.CancelledUnseen)
    Refusal { message: said.message, help: said.help ?? "" }
}

fn not_a_task(mut cx: TypeCx, t: ExprId) -> TypeId {
    let n = cx.name_at(t)
    cx
