    /// statement, so a per-decl walk asks the same marks twice — once
    /// with the owner's claims and once with none, and the second run
    /// refuses what the first allowed.
    fn hold_marks_to_a_reader(f: FileId, p: Parsed, vis: Namespace, gathered: List<DeclId>) {
        for s in p.stmts { self.hold_the_marks_of(f, s, p, vis, gathered) }
    }

    fn hold_the_marks_of(f: FileId, s: StmtId, p: Parsed, vis: Namespace, gathered: List<DeclId>) {
        self.speak_unread_own_marks(f, s, p, vis, gathered)
        let worn = self.worn_marks(f, s, p)
        if worn.is_empty() { return }
        let owner? = self
            .decls
            .decls_of_file(f)
            .find((c: DeclId) -> same_stmt(self.decls.decl(c).stmt, s)) else {
            return
