mk fate_for_graveyard <<'EOF'
use @std.meta.{fate_for}

export component crew<T> {
    run: fn(T) -> Result<int, string>
    @fate_for(run) graveyard: string? = null
}

fn deliver(n: int) -> Result<int, string> { .Ok(n) }

fn go() -> int {
    crew<int> buried {
        run: deliver
        graveyard: "kept"
    }
    crew<int> loose {
        run: deliver
    }
    let _ = [buried.graveyard, loose.graveyard]
    1
}
println("${go()}")
EOF
mk fate_for_named <<'EOF'
use @std.meta.{fate_for}

export component crew<T> {
    each: fn(T) -> Result<int, string>
    @fate_for(each) dead: string? = null
    @fate_for(each) spare: string = "own letter"
}

fn deliver(n: int) -> Result<int, string> { .Ok(n) }

fn go() -> string {
    crew<int> sender {
        each: deliver
        dead: "undeliverable"
    }
    "${sender.dead ?? "none"} ${sender.spare}"
}
println(go())
EOF
