/// A COMPONENT THAT HOLDS A HANDLER WHICH CAN FAIL NAMES A FATE:
/// `flow.no_fate`. The handler is structural — a field whose value
/// answers `Result` — and the fate is the component's own `dead:`
/// field, set. A component that declares no `dead:` field is not one
/// that owes a fate.
fn fate_law(mut cx: TypeCx, x: ExprId) {
    let parts? = cx.view.store.struct_lit_parts(x) else { return }
    let handler? = parts.values.find((v) -> fails(cx, v)) else { return }
    let sig? = cx.fields_of(cx.type_at(x)) else { return }
    if !sig.names.contains(fate_field) { return }
    let slot = parts.fields.index_of(fate_field)
    if slot >= 0 && !(cx.shape_at(parts.values[slot]) is .Null) { return }
    cx.emit(no_fate(cx.loc_of(handler), cx.view.store.struct_lit_name(x) ?? "this component"))
}

/// The field a component names its fate in.
const fate_field = "dead"

/// Whether a value's type is a fn whose answer can fail.
fn fails(cx: TypeCx, v: ExprId) -> bool {
    match cx.shape_at(v) { .Fn(_, _, ret) -> is_failure(cx, ret), rest -> false }
}

/// Whether a type is a `Result`.
/// A COMPONENT THAT HOLDS A HANDLER WHICH CAN FAIL NAMES A FATE: the instance at `e`, of `instance`, a
/// component whose record has the fate field, holding a fn that answers a `Result` and leaving its
/// fate unset or `null`, refused at the handler.
fn fate_judged(mut cx: Checking, e: ExprId, instance: SignedType?) {
    let ty? = instance else { return }
    let x? = cx.store.expansion_of(e) else { return }
    let lit? = cx.store.struct_lit_parts(x) else { return }
    let record? = cx.record_of(ty) else { return }
    if !record.fields.any(it.name == FATE_FIELD) { return }
    let handler? = lit.values.find((v) -> can_fail(cx.type_of(v))) else { return }
    let slot = lit.fields.index_of(FATE_FIELD)
    if slot >= 0 && !written_null(cx, lit.values[slot]) { return }
    cx.fateless(handler, lit.name)
}

/// The field a component names its fate in.
const FATE_FIELD: string = "dead"

/// Whether a value of `ty` is a fn whose answer can fail.
fn can_fail(ty: SignedType?) -> bool {
    let t? = ty else { return false }
    t.head is .Function && t.answer?.owns(OwnType.Result) ?? false
}

/// Whether `v` is written `null`.
fn written_null(cx: Checking, v: ExprId) -> bool { cx.store.expr(v) is .NullLit }
