fn misses_in(engine: QueryEngine, t: TypedNodes) -> List<MissAt> {
    let inferred = indexed(
        flatten(
            [flatten([t.store.every_expr(b) for b in inferred_body(t.store, ExprId { index: i })])
                .concat(held_call(t.store, ExprId { index: i })) for i in t.lo..t.hi],
        )
            .concat(annotation_calls(t.store)),
    )
    let scope = MissScope {
        values: statement_values(t.store),
        generic: [p! for s in t.store.stmt_ids() for p in [t.store.fn_parts(s)] if p != null && !p!.tparams.is_empty()],
    }
    [kept_miss(m) for i in t.lo..t.hi for e in [ExprId { index: i }] if t.store.home_of(e) == null && t.store.minted_for(e) == null && !inferred.has("${i}") for m in miss_at(engine, t, e, scope)]
        .concat(
            [kept_miss(m) for i in t.lo..t.hi for e in [ExprId { index: i }] if t.store.home_of(e) == null && t.store.minted_for(e) != null for m in literal_miss(engine, t, e).concat(owned_literal_miss(engine, t, e))],
        )
}

/// Every node an annotation's call holds, a statement's or a seat's: what it hands its annotation
/// is the annotation's to read, never a call's arguments.
fn annotation_calls(store: SyntaxArena) -> List<ExprId> {
    let stmts = [StmtId { index: i } for i in 0..store.stmts.count()]
    let written = [a.callee for s in stmts for a in store.annotations_of(s)]
        .concat([x for s in stmts for a in store.annotations_of(s) for x in a.args])
    let seats = [m.call! for s in stmts for p in store.declared_fields(s).concat(store.declared_params(s)) for m in p.marks if m.call != null]
    flatten([store.every_expr(c) for c in written.concat(seats)])
}

/// The body of the lambda `e` where a seat of it is written without a type; nothing for any other
/// node.
fn inferred_body(store: SyntaxArena, e: ExprId) -> List<ExprId> {
    match store.expr(e) {
        .Lambda(params, body) -> if params.any(it.ty == null) { [body] } else { [] },
        .BlockLambda(seats, body) -> if seats.any(it.ty == null) { [body] } else { [] },
        rest -> [],
    }
}

/// The call a trailing block makes of the node it holds, that node, and what a pipe's stage holds,
/// which the pipe completes; nothing for any other.
fn held_call(store: SyntaxArena, e: ExprId) -> List<ExprId> {
    /// hidden branches and statement bodies included.
    fn every_expr(root: ExprId) -> List<ExprId> {
        flatten([self.every_expr(k) for k in self.reached(root)]).concat([root])
    }

    fn stmts_exprs(ids: List<StmtId>) -> List<ExprId> {
        flatten([self.stmt_children(s) for s in ids])
    }

    /// AN OPTIONAL EXPRESSION IS ONE VALUE, absence included — a
    /// block that leaves instead of answering, a comprehension with
    /// no guard, a field with no default. Fixed arity, so it stands
    /// in a parts list directly, as `type_fp` does for a type.
    /// A mark's arguments as written: its call's, past the value.
    fn mark_args(m: Mark) -> List<ExprId> {
        let q? = m.call else { return [] }
        let body? = self.expr(q).body_of() else { return [] }
        let stmts: List<StmtId> = match body.view {
            .Verbatim(ss, _) -> ss,
            .None or .Expanded(_) -> [],
        }
        let first? = stmts.first() else { return [] }
        let call? = self.answer_of(first) else { return [] }
        match self.expr(call) { .Call(_, _, args) -> args.slice(1, args.length), _ -> [] }
    }

    fn opt_fp(value: ExprId?) -> int {
        if value == null { return 0 }
        fp(128, [self.expr_fingerprint(value!)])
    }

    /// The fingerprints of expression children, in order.
    fn expr_fps(ids: List<ExprId>) -> List<int> {
        [self.expr_fingerprint(k) for k in ids]
    }
