/// field, set. A component that declares no `dead:` field is not one
/// that owes a fate.
fn fate_law(mut cx: TypeCx, e: ExprId, x: ExprId) {
    let parts? = cx.view.store.struct_lit_parts(x) else { return }
    let handler? = parts.values.find((v) -> fails(cx, v)) else { return }
    let own? = fate_of(cx, cx.type_at(x)) else { return }
    if fate_named(cx, parts, own) { return }
    let word = cx.view.store.struct_lit_name(x) ?? "this component"
    let queues = [v for v in parts.values if fate_of(cx, cx.type_at(v))?.declares ?? false]
    if queues.is_empty() {
        if own.declares { cx.emit(no_fate(cx.loc_of(handler), word)) }
        return
    }
    if queues.any((q) -> queue_lettered(cx, q)) { return }
    let named = cx.view.store.bound_as(e) ?? word
    cx
        .emit(
            said_as(
                "flow.no_fate",
                cx.loc_of(handler),
                fate_unqueued(named, cx.view.store.ident_name(queues[0]) ?? word),
            ),
        )
}

/// What a record a value is says of its fate field: whether it declares one, and whether that field's
/// default is a value.
type FateField = { declares: bool, valued: bool }

/// The fate field of the record `ty` is, where `ty` is a record the program declares; absent for any
/// other type. A record no component declares has its fields' defaults unread, as none.
fn fate_of(cx: TypeCx, ty: TypeId) -> FateField? {
    let sig? = cx.fields_of(ty) else { return null }
    if !sig.names.contains(fate_field) { return FateField { declares: false, valued: false } }
    let d? = record_decl(cx, ty) else { return fate_unvalued() }
    let c? = cx.view.decls.component_parts_of(d) else { return fate_unvalued() }
    let store = cx.view.decls.store(d)
    FateField {
        declares: true,
        valued: c.fields().any((p) -> p.name.of == fate_field && store.defaults_to_value(p)),
    }
}

/// A fate field declared whose default no declaration says is a value.
fn fate_unvalued() -> FateField { FateField { declares: true, valued: false } }

/// The declaration a record type names, plain or applied.
fn record_decl(cx: TypeCx, ty: TypeId) -> DeclId? {
    match cx.view.types.shape_of(ty) { .Struct(d, _) or .App(d, _, _) -> d, rest -> null }
}

/// Whether a literal of a record whose fate field is `own` names its fate: the field written other
/// than `null`, or left to a default that is a value.
fn fate_named(cx: TypeCx, parts: StructLitParts, own: FateField) -> bool {
    let slot = parts.fields.index_of(fate_field)
    if slot >= 0 { return !(cx.shape_at(parts.values[slot]) is .Null) }
    own.valued
}

/// Whether the queue the value `q` names has a letter: the named instance it reads names its own fate;
/// one no name traces to an instance is taken as lettered.
fn queue_lettered(cx: TypeCx, q: ExprId) -> bool {
    let inst? = cx.view.store.instance_named(q) else { return true }
    let x? = cx.view.store.expansion_of(inst) else { return true }
    let parts? = cx.view.store.struct_lit_parts(x) else { return true }
    let own? = fate_of(cx, cx.type_at(q)) else { return true }
    fate_named(cx, parts, own)
}

