/// The type arguments an instance that writes none leaves its component's parameters: each one the
/// instance's fields decide, so inferred.
fn inferred_args(cx: Checking, declared: SignedType) -> List<SignedType> {
    [headed_type(TypeHead.Inferred) for _p in 0..cx.record_of(declared)?.params ?? 0]
}

/// A COMPONENT THAT HOLDS A HANDLER WHICH CAN FAIL NAMES A FATE: the instance at `e`, of `instance`,
/// holding a fn that answers a `Result`, refused at the handler where no letter takes its failures —
/// its own fate field, written or defaulted to a value, else the letter of the queue a field of it
/// holds. One with neither a fate field nor a queue owes none, and a queue no name traces to its
/// instance is taken as lettered: only a fate known missing is refused.
fn fate_judged(mut cx: Checking, e: ExprId, instance: SignedType?) {
    let ty? = instance else { return }
    let x? = cx.store.expansion_of(e) else { return }
    let lit? = cx.store.struct_lit_parts(x) else { return }
    let record? = cx.record_of(ty) else { return }
    let handler? = lit.values.find((v) -> can_fail(cx.type_of(v))) else { return }
    if fated(cx, lit, record) { return }
    let queues = [v for v in lit.values if lettered(cx, cx.type_of(v)) != null]
    if queues.is_empty() {
        if record.fields.any(it.name == FATE_FIELD) { cx.fateless(handler, lit.name, null) }
        return
    }
    if queues.any((q) -> queue_fated(cx, q)) { return }
    cx
        .fateless(handler, cx.store.bound_as(e) ?? lit.name, cx.store.ident_name(queues[0]) ?? lit.name)
}

/// Whether the literal `lit` of `record` names its own fate: its fate field written other than `null`,
/// or left to a default that is a value.
fn fated(cx: Checking, lit: StructLitParts, record: RecordShape) -> bool {
    let slot = lit.fields.index_of(FATE_FIELD)
    if slot >= 0 { return !written_null(cx, lit.values[slot]) }
    record.fields.find(it.name == FATE_FIELD)?.valued ?? false
}

/// The record a value of `ty` is where it declares a fate field — a queue another reads; absent for
/// any other type.
fn lettered(cx: Checking, ty: SignedType?) -> RecordShape? {
    let held? = ty else { return null }
    let record? = cx.record_of(held) else { return null }
