export component box<T> {
    name: string = ""
    dead: string? = null
}

export component crew<T> {
    reads: box<T>
    each: fn(T) -> Result<int, string>
    dead: string? = null
}

fn deliver(n: int) -> Result<int, string> { .Ok(n) }

fn go() -> int {
    box<int> emails {
        name: "emails"
        dead: "undeliverable"
    }
    box<int> plain {
        name: "plain"
    }
    crew sender {
        reads: emails
        each: deliver
    }
    crew loose {
        reads: plain
        each: deliver
    }
    let _ = [sender.reads.name, loose.reads.name]
    1
}
println("${go()}")
