/// A component read as a record: its head in order, the `List` fields
/// its instance's statements may fill — never a `state` one, a place the
/// instance keeps or is handed — its one fn field — an event's
/// handler is heard, never a body — and its events. `components` are the names its file declares
/// components by: a list of one takes that component's instances alone.
export fn record_of(store: SyntaxArena, c: ComponentParts, components: List<string>) -> Record {
    let fields = c.fields()
    let arrow_fields = [p for p in fields if p.ty?.arrow ?? false]
    Record {
        head: [p.name.of for p in c.head],
        slots: [ChildSlot {
            name: p.name.of,
            of: element_name(p),
            gathers: !components.contains(element_name(p)),
            default: p.marks.any(it.name == default_mark),
        } for p in fields if lists(p) && !p.state],
        named: fields.any(it.name.of == "name"),
        checks: member(store, c, "check") != null,
        fn_field: if arrow_fields.length == 1 { arrow_fields[0].name.of } else { null },
        fn_optional: arrow_fields.length == 1 && answers_nullable(arrow_fields[0].ty),
        events: [Event {
            name: e.name,
            says: [s.name.of for s in e.says],
            default: e.holder.marks.any(it.name == default_mark),
        } for e in c.events()],
        words: fields.any(says_words(it)) || !c.spreads.is_empty(),
    }
}

/// Whether a field is spelled with the type `Words`. The builder runs before
/// types resolve, so this and a spread — whose fields are another
/// declaration's — are only a HINT that the component may take a closure that
/// says its text again, so the instance mints one beside it; the lowering
/// fills a slot only when its resolved type is `@std/meta`'s own.
@derive(Fingerprint)
@derive(Exemplar)
export type Record = {
    head: List<string>,
    slots: List<ChildSlot>,
    named: bool,
    checks: bool,
    fn_field: string? = null,
    fn_optional: bool = false,
    events: List<Event> = [],
    words: bool = false,
}

