/// A seat a call's arguments feed: whether it's `mut`, and the name an argument fills it by, absent
/// for a fn value's.
@derive(Saved)
type FedSeat = { mutable: bool, name: string? = null }

/// Signed seats as their arguments feed them.
fn fed_seats(seats: List<SignedSeat>) -> List<FedSeat> { [FedSeat { mutable: s.mutable, name: s.name } for s in seats] }

/// Written params as their arguments feed them.
fn params_fed(params: List<Param>) -> List<FedSeat> { [FedSeat { mutable: p.promises.mutable, name: p.name.of } for p in params] }

/// The seat the argument `j` of `args` fills: a named one the seat of its name, one written by
/// position the next seat in order; absent for a spread, a name no seat has, or one past the seats.
fn seat_taking(store: SyntaxArena, seats: List<FedSeat>, args: List<ExprId>, j: int) -> int? {
    if store.spread_operand(args[j]) != null { return null }
    let label = store.arg_label(args[j])
    if label != null { return seats.find_index(it.name == label) }
    let at = args.take(j).filter(store.arg_label(it) == null).length
    if at < seats.length { at } else { null }
}""")
