cd /work/avra/packages/std-avrac/src && python3 - <<'EOF'
def edit(p, old, new, cnt=1):
    s=open(p).read(); assert s.count(old)>=cnt, (p, old[:70], s.count(old)); s=s.replace(old,new); open(p,'w').write(s)
p='features/components/mod.av'
edit(p, "use features.{LanguageFeature}", "use features.{LanguageFeature, RefusalRow, RefusalWords}")
edit(p, '''        "flow.no_fate"            | "a handler that can fail must name a fate for its failure"
    }''', '''        "flow.no_fate"            | "a handler that can fail must name a fate for its failure"
        "parse.instance_spread"   | "an instance is built from its settings, children and defaults, never a spread"
    }''')
s=open(p).read()
n=s.count("( stmts:setting | stmts:stmt | BREAK )*")
print("lists",n)
s=s.replace("( stmts:setting | stmts:stmt | BREAK )*","( stmts:setting | stmts:stmt | instance_spread | BREAK )*")
s=s.replace('''            handler_seat = name:NAME -> Record.ParamSyntax''','''            instance_spread = ".." postfix ( "," | END ) -> Refusal.instance_spread
            handler_seat = name:NAME -> Record.ParamSyntax''')
s=s.replace('''        diags: codes
    }
    components
}''','''        diags: codes
        refusals: [RefusalRow { name: "instance_spread", kind: "parse.instance_spread", voice: instance_spread }]
    }
    components
}

/// A spread written in an instance's block.
fn instance_spread() -> RefusalWords {
    RefusalWords {
        message: "an instance is built from its settings, its children and its defaults, and a spread is none of them",
        help: "copy a built instance and change what differs — `base with { w: 1 }`",
    }
}''')
open(p,'w').write(s)
p='compiler/dev/remedies.av'
s=open(p).read()
i=s.rindex("            becomes: Then.Clean,\n        },\n    ]\n}")
add='''            becomes: Then.Clean,
        },
        RemedyRow {
            kind: "parse.instance_spread",
            says: "an instance is built from its settings, its children and its defaults",
            refused: Witness
                .Source(
                    "component tray {\\n    w: int = 0\\n    h: int = 0\\n}\\nlet base = tray { h: 2 }\\nlet t = tray { ..base, w: 1 }\\nt.w + t.h",
                ),
            applied: Witness
                .Source(
                    "component tray {\\n    w: int = 0\\n    h: int = 0\\n}\\nlet base = tray { h: 2 }\\nlet t = base with { w: 1 }\\nt.w + t.h",
                ),
            becomes: Then.Clean,
        },
    ]
}'''
s=s[:i]+add+s[i+len("            becomes: Then.Clean,\n        },\n    ]\n}"):]
open(p,'w').write(s)
EOF
cd /work/avra && . /etc/profile.d/avra.sh && build/avra fmt --write packages/std-avrac/src/features/components/mod.av packages/std-avrac/src/compiler/dev/remedies.av | tail -1; AVRA_PROGRAM_NET=0 make try > /tmp/claude-0/tryH.log 2>&1; echo rc=$?; grep -v "^cc " /tmp/claude-0/tryH.log | tail -8 | cut -c1-300

