/// Whether the token at `i` is a component's word opening an instance.
/// An imported word always does. A word the file's own MODULE declares
/// is reserved nowhere, so it opens one only where the line says so: a
/// head value after it, or — past its type arguments — a block, where
/// an expression stands. Where a type stands (a declaration's name, an
/// annotation, a fn signature's answer) the word stays the type's.
fn opens_instance(
    ts: List<Token>,
    i: int,
    components: List<string>,
    named: List<string>,
    keywords: List<string>,
) -> bool {
    let t = ts[i]
    if t.kind != TokenKind.Name { return false }
    if components.contains(t.text) { return true }
    if !named.contains(t.text) { return false }
    let head = after_type_args(ts, i + 1)
    heads_instance(ts, head, keywords) ||
        head < ts.length &&
            ts[head].lit_matches("{") &&
            !types_here(ts, i) &&
            !patterns_here(ts, i, head) &&
            instance_only(ts, head)
}

