}

fn checked(main: string) -> Judged {"""
assert old in s; s=s.replace(old,new,1)
old="""    given "binders" {"""
new="""    given "a default only a run can build" {
        then "one the check never reads is never built, and the check judges the instance" {
            refused_in(
                provided("use @x.c.{tally}\\ntally t { n: 0 }\\nt.n", runs()),
