            provided("use @x.c.{herald}\\nherald h { n: 0 }\\nh.n", runs())
                .warnings()
                .contains("this instance's `check` cannot run at compile time")
        }
    }
    given "binders" {"""
assert old in s; s=s.replace(old,new,1)
open(p,'w').write(s)
EOF
