/// imports: a build judges its reach, as `check` and `test` judge the package — in the order the
/// package's files are read, or, where a manifest it stands on refuses it, those manifests alone.
export fn entry_erring(engine: QueryEngine, entry: SourceFileAddress, package: string) -> List<
    SourceFileAddress,
> {
    let manifests = manifests_refused(engine, package)
    if !manifests.is_empty() { return manifests }
    mut reached: Map<string, bool> = {}
    for f in entry_files(engine, entry) { reached.set(spelled_file(f), true) }
    [f for f in program_files(engine, package) if reached.has(spelled_file(f)) && file_erring(engine, f).errors > 0]
